package com.airbnb.lottie.utils;

/**
 * Standalone regression test for MiscUtils.floorMod(float, float).
 *
 * The buggy implementation at MiscUtils.java:63-64 is:
 *   static int floorMod(float x, float y) {
 *     return floorMod((int) x, (int) y);
 *   }
 *
 * This casts both arguments to int BEFORE computing floorMod, losing all
 * fractional precision. The return type is int, so fractional results are
 * impossible.
 *
 * The correct floorMod(x, y) = x - y * floor(x/y) should preserve fractional
 * precision when given float inputs. This test embeds the exact buggy logic
 * from MiscUtils.java so it can be compiled and run standalone with javac.
 *
 * Run: javac MiscUtilsFloorModStandaloneTest.java && java com.airbnb.lottie.utils.MiscUtilsFloorModStandaloneTest
 */
public class MiscUtilsFloorModStandaloneTest {

  // -----------------------------------------------------------------------
  // Exact copy of the buggy floorMod implementation from MiscUtils.java:63-78
  // -----------------------------------------------------------------------
  static int floorMod(float x, float y) {
    return floorMod((int) x, (int) y);
  }

  private static int floorMod(int x, int y) {
    return x - y * floorDiv(x, y);
  }

  private static int floorDiv(int x, int y) {
    int r = x / y;
    boolean sameSign = (x ^ y) >= 0;
    int mod = x % y;
    if (!sameSign && mod != 0) {
      r--;
    }
    return r;
  }

  /**
   * Helper: correct float floorMod that preserves fractional precision.
   * floorMod(x, y) = x - y * floor(x / y)
   */
  private static float correctFloorMod(float x, float y) {
    return x - y * (float) Math.floor(x / y);
  }

  private static int failures = 0;
  private static int testsRun = 0;

  private static void assertEquals(String message, float expected, float actual, float delta) {
    testsRun++;
    if (Math.abs(expected - actual) > delta) {
      System.err.println("FAIL: " + message);
      System.err.println("  Expected: " + expected);
      System.err.println("  Actual:   " + actual);
      failures++;
    } else {
      System.out.println("PASS: " + message);
    }
  }

  public static void main(String[] args) {
    System.out.println("=== MiscUtils.floorMod(float,float) Bug Regression Tests ===\n");

    // Test 1: floorMod(5.7, 3.2) should return 2.5, not 2
    {
      float expected = 2.5f;
      float actual = floorMod(5.7f, 3.2f);
      assertEquals(
          "floorMod(5.7f, 3.2f) should preserve fractional precision (correct: " + expected + ")",
          expected, actual, 0.001f);
    }

    // Test 2: floorMod(-1.5, 3.0) should return 1.5, not 2
    {
      float expected = 1.5f;
      float actual = floorMod(-1.5f, 3.0f);
      assertEquals(
          "floorMod(-1.5f, 3.0f) should return " + expected,
          expected, actual, 0.001f);
    }

    // Test 3: floorMod(0.5, 0.3) should return 0.2 (buggy code: division by zero!)
    {
      float expected = 0.2f;
      try {
        float actual = floorMod(0.5f, 0.3f);
        assertEquals(
            "floorMod(0.5f, 0.3f) should return " + expected,
            expected, actual, 0.001f);
      } catch (ArithmeticException e) {
        testsRun++;
        System.err.println("FAIL: floorMod(0.5f, 0.3f) threw ArithmeticException (division by zero in buggy code)");
        failures++;
      }
    }

    // Test 4: Trim path scenario - floorMod(20.8, 10.3) should return 0.2, not 0
    {
      float pathLength = 10.3f;
      float newStart = 20.8f;
      float expected = 0.2f;
      float actual = floorMod(newStart, pathLength);
      assertEquals(
          "Trim path: floorMod(" + newStart + ", " + pathLength + ") should return " + expected,
          expected, actual, 0.001f);
    }

    // Test 5: Verify correctFloorMod gives the right answers
    System.out.println("\nCorrect floorMod values (for reference):");
    System.out.println("  correctFloorMod(5.7f, 3.2f) = " + correctFloorMod(5.7f, 3.2f));
    System.out.println("  correctFloorMod(-1.5f, 3.0f) = " + correctFloorMod(-1.5f, 3.0f));
    System.out.println("  correctFloorMod(0.5f, 0.3f) = " + correctFloorMod(0.5f, 0.3f));
    System.out.println("  correctFloorMod(20.8f, 10.3f) = " + correctFloorMod(20.8f, 10.3f));

    // Summary
    System.out.println("\n=== Results: " + testsRun + " tests, " + failures + " failures ===");
    if (failures > 0) {
      System.out.println("BUG CONFIRMED: floorMod(float, float) loses fractional precision");
      System.exit(1);
    } else {
      System.out.println("All tests passed");
      System.exit(0);
    }
  }
}

