package com.airbnb.lottie.utils;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class MiscUtilsTest {

  @Test
  public void floorModFloatPreservesFractionalPrecision() {
    // floorMod(x, y) = x - y * floor(x / y)
    // For x=5.7f, y=3.2f:
    //   x/y = 1.78125, floor = 1
    //   floorMod = 5.7 - 3.2 * 1 = 2.5
    // The buggy code casts to int first: floorMod(5, 3) = 2, losing fractional precision.
    float result = MiscUtils.floorMod(5.7f, 3.2f);
    assertEquals("floorMod(5.7f, 3.2f) should preserve fractional precision", 2.5f, result, 0.001f);
  }

  @Test
  public void floorModFloatWithNegativeDividend() {
    // floorMod(-1.5f, 3.0f):
    //   x/y = -0.5, floor = -1
    //   floorMod = -1.5 - 3.0 * (-1) = 1.5
    // The buggy code: floorMod(-1, 3) = -1 - 3 * (-1) = 2 (wrong)
    float result = MiscUtils.floorMod(-1.5f, 3.0f);
    assertEquals("floorMod(-1.5f, 3.0f) should return 1.5f", 1.5f, result, 0.001f);
  }

  @Test
  public void floorModFloatSmallFractionalValues() {
    // floorMod(0.5f, 0.3f):
    //   x/y = 1.666..., floor = 1
    //   floorMod = 0.5 - 0.3 * 1 = 0.2
    // The buggy code: floorMod(0, 0) = 0/0 division by zero or floorMod(0,0) crash
    float result = MiscUtils.floorMod(0.5f, 0.3f);
    assertEquals("floorMod(0.5f, 0.3f) should return 0.2f", 0.2f, result, 0.001f);
  }
}

