package com.airbnb.lottie.compose

import android.graphics.Rect
import androidx.collection.LongSparseArray
import androidx.collection.SparseArrayCompat
import com.airbnb.lottie.LottieComposition
import com.airbnb.lottie.model.Marker
import org.junit.Assert.*
import org.junit.Test

class LottieClipSpecTest {

    @Test
    fun testMinFrame() {
        val spec = LottieClipSpec.Frame(min = 20)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(1f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMaxFrame() {
        val spec = LottieClipSpec.Frame(max = 20)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0f, spec.getMinProgress(composition))
        assertEquals(0.5f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMaxFrameNotInclusive() {
        val spec = LottieClipSpec.Frame(max = 20, maxInclusive = false)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0f, spec.getMinProgress(composition))
        assertEquals(0.475f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMinAndMaxFrame() {
        val spec = LottieClipSpec.Frame(min = 20, max = 30)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(0.75f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMinAndMaxFrameNotExclusive() {
        val spec = LottieClipSpec.Frame(min = 20, max = 30, maxInclusive = false)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(0.725f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMinProgress() {
        val spec = LottieClipSpec.Progress(min = 0.5f)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(1f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMaxProgress() {
        val spec = LottieClipSpec.Progress(max = 0.5f)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0f, spec.getMinProgress(composition))
        assertEquals(0.5f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMinAndMaxProgress() {
        val spec = LottieClipSpec.Progress(min = 0.5f, max = 0.75f)
        val composition = createComposition(endFrame = 40f)
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(0.75f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMinMarker() {
        val spec = LottieClipSpec.Markers(min = "start")
        val composition = createComposition(endFrame = 40f, markers = listOf(Marker("start", 20f, 10f)))
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(1f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMaxMarker() {
        val spec = LottieClipSpec.Markers(max = "end")
        val composition = createComposition(endFrame = 40f, markers = listOf(Marker("end", 20f, 10f)))
        assertEquals(0f, spec.getMinProgress(composition))
        assertEquals(0.5f, spec.getMaxProgress(composition))
    }


    @Test
    fun testMaxMarkerExclusive() {
        val spec = LottieClipSpec.Markers(max = "end", maxInclusive = false)
        val composition = createComposition(endFrame = 40f, markers = listOf(Marker("end", 20f, 10f)))
        assertEquals(0f, spec.getMinProgress(composition))
        assertEquals(0.475f, spec.getMaxProgress(composition))
    }


    @Test
    fun testMinAndMaxMarker() {
        val spec = LottieClipSpec.Markers(min = "start", max = "end")
        val composition = createComposition(endFrame = 40f, markers = listOf(Marker("start", 20f, 10f), Marker("end", 30f, 10f)))
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(0.75f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMinAndMaxMarkerExclusive() {
        val spec = LottieClipSpec.Markers(min = "start", max = "end", maxInclusive = false)
        val composition = createComposition(endFrame = 40f, markers = listOf(Marker("start", 20f, 10f), Marker("end", 30f, 10f)))
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(0.725f, spec.getMaxProgress(composition))
    }

    @Test
    fun testMarker() {
        val spec = LottieClipSpec.Marker("span")
        val composition = createComposition(endFrame = 40f, markers = listOf(Marker("span", 20f, 10f)))
        assertEquals(0.5f, spec.getMinProgress(composition))
        assertEquals(0.75f, spec.getMaxProgress(composition))
    }

    @Test
    fun testFrameWithNonZeroStartFrame() {
        // startFrame=10, endFrame=50: frame 30 should be (30-10)/(50-10) = 0.5
        val spec = LottieClipSpec.Frame(min = 30, max = 40)
        val composition = createComposition(startFrame = 10f, endFrame = 50f)
        // Verify getProgressForFrame agrees
        assertEquals(0.5f, composition.getProgressForFrame(30f), 0.001f)
        assertEquals(0.5f, spec.getMinProgress(composition), 0.001f)
        assertEquals(0.7f, spec.getMaxProgress(composition), 0.001f)
    }

    @Test
    fun testFrameMinOnlyWithNonZeroStartFrame() {
        // startFrame=10, endFrame=50: frame 30 should be (30-10)/(50-10) = 0.5
        val spec = LottieClipSpec.Frame(min = 30)
        val composition = createComposition(startFrame = 10f, endFrame = 50f)
        assertEquals(0.5f, spec.getMinProgress(composition), 0.001f)
    }

    @Test
    fun testFrameMaxOnlyWithNonZeroStartFrame() {
        // startFrame=10, endFrame=50: frame 30 should be (30-10)/(50-10) = 0.5
        val spec = LottieClipSpec.Frame(max = 30)
        val composition = createComposition(startFrame = 10f, endFrame = 50f)
        assertEquals(0.5f, spec.getMaxProgress(composition), 0.001f)
    }

    @Test
    fun testMarkersWithNonZeroStartFrame() {
        // startFrame=10, endFrame=50: marker at frame 30 should be (30-10)/(50-10) = 0.5
        val spec = LottieClipSpec.Markers(min = "start", max = "end")
        val composition = createComposition(startFrame = 10f, endFrame = 50f, listOf(
            Marker("start", 30f, 10f),
            Marker("end", 40f, 10f)
        ))
        assertEquals(0.5f, spec.getMinProgress(composition), 0.001f)
        assertEquals(0.7f, spec.getMaxProgress(composition), 0.001f)
    }

    @Test
    fun testMarkerWithNonZeroStartFrame() {
        // startFrame=10, endFrame=50: marker at frame 30 with duration 10 should end at frame 40
        // min = (30-10)/(50-10) = 0.5, max = (40-10)/(50-10) = 0.75
        val spec = LottieClipSpec.Marker("span")
        val composition = createComposition(startFrame = 10f, endFrame = 50f, listOf(
            Marker("span", 30f, 10f)
        ))
        assertEquals(0.5f, spec.getMinProgress(composition), 0.001f)
        assertEquals(0.75f, spec.getMaxProgress(composition), 0.001f)
    }

    private fun createComposition(startFrame: Float = 0f, endFrame: Float, markers: List<Marker> = emptyList()): LottieComposition {
        val composition = LottieComposition()
        composition.init(
            Rect(),
            startFrame,
            endFrame,
            30f,
            emptyList(),
            LongSparseArray(),
            emptyMap(),
            emptyMap(),
            1f,
            SparseArrayCompat(),
            emptyMap(),
            markers,
            0,
            0,
        )
        return composition
    }
}

