import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

public class KeyframesParserTest {

  /**
   * Tests that when the last keyframe has a non-null startValue but null endValue,
   * it should NOT be removed. The comment in setEndFrames says "The only purpose the last
   * keyframe has is to provide the end frame of the previous keyframe." This implies the
   * last keyframe should only be removed when it serves no purpose at all — i.e. when
   * BOTH startValue AND endValue are null. Using OR (||) is too aggressive and removes
   * the last keyframe even when it has a meaningful startValue.
   */
  @Test
  public void setEndFrames_shouldKeepLastKeyframeWhenStartValueIsNonNull() {
    List<Keyframe<String>> keyframes = new ArrayList<>();

    // First keyframe: non-null startValue and endValue
    // Using the simple constructor which sets both to the same value
    keyframes.add(new Keyframe<>("firstValue"));

    // Last keyframe: has non-null startValue but null endValue
    // This keyframe has meaning — its startValue is "lastValue"
    // We need to use the LottieComposition-based constructor with composition=null
    Keyframe<String> last = new Keyframe<String>(
        (LottieComposition) null, "lastValue", null, null, 20f, null
    );
    keyframes.add(last);

    assertEquals(2, keyframes.size());

    KeyframesParser.setEndFrames(keyframes);

    // The last keyframe should NOT be removed because it has a meaningful startValue
    // The bug is that (startValue == null || endValue == null) evaluates to true
    // because endValue is null, even though startValue is NOT null
    assertEquals("Last keyframe with non-null startValue should be kept", 2, keyframes.size());
    assertEquals("lastValue", keyframes.get(1).startValue);
  }

  /**
   * Tests that when the last keyframe has BOTH startValue and endValue null,
   * it SHOULD be removed (since it serves no purpose other than providing
   * the end frame of the previous keyframe).
   */
  @Test
  public void setEndFrames_shouldRemoveLastKeyframeWhenBothValuesNull() {
    List<Keyframe<String>> keyframes = new ArrayList<>();

    // First keyframe with a value
    keyframes.add(new Keyframe<>("firstValue"));

    // Last keyframe: both startValue and endValue are null
    Keyframe<String> last = new Keyframe<String>(
        (LottieComposition) null, null, null, null, 20f, null
    );
    keyframes.add(last);

    assertEquals(2, keyframes.size());

    KeyframesParser.setEndFrames(keyframes);

    // The last keyframe SHOULD be removed because it has no meaningful values
    assertEquals("Last keyframe with both null values should be removed", 1, keyframes.size());
  }
}

