public class GradientColorBugTest {
    public static void main(String[] args) {
        // Create a gradient with stops at [0f, 1f] and 2 colors
        GradientColor gc = new GradientColor(new float[]{0f, 1f}, new int[]{0xFF000000, 0xFFFFFFFF});

        // Request a new position beyond the last stop (1.5f > 1f).
        // insertionPoint for 1.5f against [0f, 1f] is 2 = colors.length
        // Correct behavior: return the last color (0xFFFFFFFF)
        // Bug: falls through to else branch, accesses positions[2], causing ArrayIndexOutOfBoundsException
        try {
            GradientColor result = gc.copyWithPositions(new float[]{0f, 0.5f, 1.5f});
            // The color at position 1.5f (beyond all stops) should be the last color
            if (result.getColors()[2] != 0xFFFFFFFF) {
                System.out.println("FAIL: Expected color 0xFFFFFFFF but got 0x" + Integer.toHexString(result.getColors()[2]));
                System.exit(1);
            }
            System.out.println("PASS: copyWithPositions handled position beyond last stop correctly");
            System.exit(0);
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("FAIL: ArrayIndexOutOfBoundsException thrown when position beyond last stop: " + e.getMessage());
            System.exit(1);
        }
    }
}

